.quote-form-page {
  max-width: 48rem;
  margin: 0 auto;
  padding: 1rem;

  &__status {
    padding: 1rem;
    border-radius: 0.5rem;
    background: #f5f5f5;

    &--error {
      background: #fdecea;
      color: #611a15;
    }
  }

  &__form {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 1rem;
    align-items: start;
  }

  &__field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
  }

  &__field-config-error {
    color: #9a3412;
    font-weight: 600;
  }

  &__help {
    font-size: 0.85rem;
    color: #555;
  }

  &__error {
    font-size: 0.85rem;
    color: #b42318;
  }

  label {
    font-weight: 600;
  }

  input,
  select {
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 0.25rem;
    font: inherit;

    &:focus-visible {
      outline: 2px solid #1a73e8;
      outline-offset: 2px;
    }
  }

  input[type='checkbox'] {
    width: 1.1rem;
    height: 1.1rem;
    align-self: flex-start;
  }

  button[type='submit'] {
    grid-column: 1 / -1;
    justify-self: start;
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 0.25rem;
    background: #1a73e8;
    color: #fff;
    font-weight: 600;
    cursor: pointer;

    &:disabled {
      background: #a9c4ec;
      cursor: not-allowed;
    }

    &:focus-visible {
      outline: 2px solid #0d47a1;
      outline-offset: 2px;
    }
  }

  button[type='button'] {
    padding: 0.5rem 1rem;
    border: 1px solid #1a73e8;
    border-radius: 0.25rem;
    background: #fff;
    color: #1a73e8;
    cursor: pointer;

    &:focus-visible {
      outline: 2px solid #1a73e8;
      outline-offset: 2px;
    }
  }
}

